//! Adversarial differential test for `Request::update_fingerprint`.
//!
//! `testdata/u15_request_fingerprint.jsonl` (generated by
//! `tools/corpus/u15/gen_fingerprint.py` against the reference implementation) covers every
//! `SessionKwargs` field, every body shape, the header fall-through chain, and — the part
//! a digest-only corpus would miss — the **ordering permutations**: query strings and
//! kwargs that must collide, headers / `json=` / form bodies that must not.
//!
//! Rows also pin `copy()`: Python's `copy()` clears the memoised `_fp`, so a copy re-hashes
//! under whatever flags it is next asked for while the original keeps its first answer.
//!
//! Rows are never removed; anything unreproducible belongs in [`DIVERGENCES`], which fails
//! if it ever starts matching.

mod u15_support;

use std::collections::{BTreeMap, HashMap};

use browser_spider::request::FingerprintOptions;
use serde_json::Value;

use u15_support::{build_request, read_corpus};

/// Rows that deliberately differ from Python, keyed by row name.
///
/// Empty. The one Python behaviour with no Rust analogue — `repr(value)` for a kwargs value
/// that `orjson` cannot serialise — is unrepresentable here (`SessionKwargs::extra` is a
/// `serde_json::Value`, which is always serialisable), so there is no row to declare.
const DIVERGENCES: &[(&str, &str)] = &[];

fn options_of(spec: &Value) -> FingerprintOptions {
    FingerprintOptions {
        include_kwargs: spec
            .get("include_kwargs")
            .and_then(Value::as_bool)
            .unwrap_or(false),
        include_headers: spec
            .get("include_headers")
            .and_then(Value::as_bool)
            .unwrap_or(false),
        keep_fragments: spec
            .get("keep_fragments")
            .and_then(Value::as_bool)
            .unwrap_or(false),
    }
}

#[test]
fn fingerprints_match_the_reference() {
    let mut corpus = read_corpus("u15_request_fingerprint.jsonl");
    let hand_written = corpus.len();
    corpus.extend(read_corpus("u15_request_fingerprint_fuzz.jsonl"));
    let divergences: HashMap<&str, &str> = DIVERGENCES.iter().copied().collect();
    let mut seen_divergences: HashMap<String, usize> = HashMap::new();
    let mut failures: Vec<String> = Vec::new();
    let mut checks = 0usize;
    let mut matched = 0usize;
    // group name -> (must_all_be_equal, [(row name, our digest)])
    let mut groups: BTreeMap<String, (bool, Vec<(String, String)>)> = BTreeMap::new();

    for row in &corpus {
        let name = row["name"].as_str().expect("name");
        let request = build_request(&row["spec"]);
        let options = options_of(&row["options"]);
        let got = hex::encode(request.update_fingerprint(options));
        let expected = row["expected"].as_str().expect("expected");

        let mut record = |label: String, got: &str, expected: &str| {
            checks += 1;
            match divergences.get(name) {
                Some(why) => {
                    *seen_divergences.entry(name.to_owned()).or_default() += 1;
                    assert_ne!(
                        got, expected,
                        "declared divergence {label:?} now MATCHES Python. Delete the row \
                         from DIVERGENCES — the port improved. Reason recorded was: {why}"
                    );
                }
                None if got == expected => matched += 1,
                None => failures.push(format!("  {label}: python {expected} != rust {got}")),
            }
        };
        record(name.to_owned(), &got, expected);

        if let Some(group) = row.get("group").and_then(Value::as_str) {
            let same = row["same_as_group"].as_bool().expect("same_as_group");
            groups
                .entry(group.to_owned())
                .or_insert_with(|| (same, Vec::new()))
                .1
                .push((name.to_owned(), got.clone()));
        }

        if let Some(expected_copy) = row.get("copy_expected").and_then(Value::as_str) {
            let copy = request.copy();
            assert!(
                copy.fingerprint().is_none(),
                "{name}: copy() must clear the memoised fingerprint"
            );
            let copy_options = options_of(&row["copy_options"]);
            let got_copy = hex::encode(copy.update_fingerprint(copy_options));
            record(format!("{name}[copy]"), &got_copy, expected_copy);
            // And the original must be untouched by the copy re-hashing.
            assert_eq!(
                hex::encode(request.update_fingerprint(copy_options)),
                got,
                "{name}: re-asking the original changed its memoised fingerprint"
            );
        }

        if let Some(expected_rehash) = row.get("rehash_expected").and_then(Value::as_str) {
            let rehash_options = options_of(&row["rehash_options"]);
            let got_rehash = hex::encode(request.update_fingerprint(rehash_options));
            record(format!("{name}[rehash]"), &got_rehash, expected_rehash);
            assert_eq!(
                got_rehash, got,
                "{name}: update_fingerprint must ignore its arguments once memoised"
            );
        }

        // Clone keeps the memoised value; that is the whole difference from copy().
        assert_eq!(
            request.clone().fingerprint().map(hex::encode).as_deref(),
            Some(got.as_str()),
            "{name}: Clone must preserve the memoised fingerprint"
        );
    }

    for (group, (same, members)) in &groups {
        assert!(
            members.len() >= 2,
            "group {group:?} has {} member(s)",
            members.len()
        );
        let mut distinct: BTreeMap<&str, Vec<&str>> = BTreeMap::new();
        for (name, digest) in members {
            distinct.entry(digest.as_str()).or_default().push(name);
        }
        if *same {
            assert_eq!(
                distinct.len(),
                1,
                "group {group:?} must collide but produced {} distinct digests: {distinct:?}",
                distinct.len()
            );
        } else {
            assert_eq!(
                distinct.len(),
                members.len(),
                "group {group:?} must NOT collide but produced {} digests for {} rows: {distinct:?}",
                distinct.len(),
                members.len()
            );
        }
    }

    for (name, why) in DIVERGENCES {
        assert!(
            seen_divergences.contains_key(*name),
            "DIVERGENCES lists {name:?}, which is not in the corpus. Never shrink a corpus \
             to raise the pass rate. Reason recorded was: {why}"
        );
    }
    assert!(
        failures.is_empty(),
        "{} of {checks} fingerprint checks differ from Python:\n{}",
        failures.len(),
        failures.join("\n")
    );
    assert!(
        hand_written >= 80,
        "the hand-written fingerprint corpus shrank to {hand_written} rows (the unit \
         requires at least 80)"
    );
    assert!(
        corpus.len() - hand_written >= 1400,
        "the fuzz corpus shrank to {} rows",
        corpus.len() - hand_written
    );
    eprintln!(
        "fingerprints: {matched}/{checks} digests match ({hand_written} hand-written + {} \
         fuzzed rows, {} ordering groups)",
        corpus.len() - hand_written,
        groups.len()
    );
}
